namespace AssetFlow.Agent;
public sealed class Worker:BackgroundService{private readonly AgentClient client;private readonly AgentState state;private readonly InventoryCollector collector;private readonly ILogger<Worker> log;public Worker(AgentClient c,AgentState s,InventoryCollector i,ILogger<Worker> l){client=c;state=s;collector=i;log=l;}protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{await client.EnsureRegistered(ct);await client.SendInventory(await collector.CollectAsync(),ct);await client.Heartbeat(ct);log.LogInformation("Inventory sent at {Time}",DateTimeOffset.Now);}catch(Exception e){log.LogError(e,"Collection failed; retrying later");}await Task.Delay(TimeSpan.FromMinutes(Math.Max(5,state.Options.CollectionMinutes)),ct);}}}
